INSERT INTO styles (key, name, accent, prompt_description, description, active, sort) VALUES
  ('wabi-sabi', 'Ваби-саби', 'sand', $wabi$Wabi-sabi interior: the beauty of imperfection, quiet and grounded. Base palette: warm grey, clay, mushroom and weathered white; contrast: umber and deep charcoal; accents: oxidized bronze and raw blackened steel. Materials: rough lime plaster with visible trowel marks, reclaimed wood, unglazed ceramics, undyed linen and raw stone. Feature wall: textured plaster with visible movement, never perfectly smooth. Lighting: soft north daylight, candles, 2200–2700K. Avoid perfect white, gloss, fake antiques, ruler-straight symmetry and decorative clutter.$wabi$, 'Фактурная штукатурка, глина, состаренная бронза и несовершенство', false, 110),
  ('organic', 'Органик модерн', 'sand', $organic$Organic Modern / Organic Luxe interior: clean contemporary silhouettes softened by natural materials, curved forms and a wellness-retreat mood. Base palette: cream, camel and warm beige; contrast: olive and terracotta; accents: brushed brass and travertine. Materials: travertine, white oak, bouclé or sherpa, raw linen and rattan. Feature wall: strongly textured stone or a softly curved niche, never a sharp decorative box. Lighting: warm 2700–3000K indirect light and sculptural fixtures. Avoid cold grey, chrome, hard angular furniture dominating the frame and glossy surfaces.$organic$, 'Природный камень, изогнутые формы, букле и тёплый латунный свет', false, 120),
  ('warm-minimal', 'Тёплый минимализм', 'dust', $warmmin$Warm Minimalism interior: fewer objects, but every object considered; hidden storage and a wellness undertone. Base palette: off-white, warm greige and sand; contrast: soft black used sparingly; one saturated accent such as terracotta or deep blue. Materials: pale natural wood, textured plaster, soft stone and linen. Feature wall: architectural and restrained — a niche, rare stone or a single textured finish, not decoration for its own sake. Lighting: 2700–3000K indirect layered light, no central chandelier. Avoid emptiness for its own sake, cold white, visible storage clutter and a furniture-showroom look.$warmmin$, 'Скрытое хранение, тёплые нейтрали и один насыщенный акцент', false, 130),
  ('biophilic', 'Биофильный', 'forest', $bio$Biophilic interior: bringing the living outdoors inside with natural materials, daylight and a restrained indoor garden. Base palette: leaf green, warm wood and stone grey; contrast: deep forest green; accents: natural clay and water elements. Materials: living wood, textured stone, cork, jute and a considered collection of 5–15 plants. Feature wall: a living wall or maximum glazing with a green view, without blocking the actual window. Lighting: full-spectrum daylight with 3000K evening light, grow-friendly placement. Avoid a single token cactus, plastic pots, blocked windows and a dry, artificial look.$bio$, 'Живые растения, дерево, камень и природный дневной свет', false, 140),
  ('heritage', 'Современная классика', 'terra', $heritage$Modern Heritage / Contemporary Classic interior: classical moldings, paneling and brass updated with contemporary furniture and lighting. The feeling of a home with layers of history, not a flipped showroom. Base palette: warm white, cream and tobacco; contrast: oxblood and deep green; accents: unlacquered brass and antique bronze. Materials: updated paneling and moldings, walnut or cherry, velvet, marble and jacquard. Feature wall: wall-colored paneling with one substantial artwork; never a museum display. Lighting: 2700K layered brass sconces, floor lamps and a restrained pendant. Avoid all-antique styling, glossy gold, copied symmetry and decorative excess.$heritage$, 'Молдинги, орех, бархат и латунь в современной подаче', false, 150),
  ('maximalism', 'Новый максимализм', 'terra', $maximal$New Maximalism interior: curated, colour-coherent and layered, not chaotic. Base palette: deep emerald, burgundy or oxblood and sapphire; contrast: gold and brass; accents: jewel tones kept within one palette. Materials: velvet, silk, brass, dark wood, vintage pieces and a gallery wall. Feature wall: a deep colour or patterned wallpaper with a composed gallery wall. Lighting: 2700K, multiple sources and dramatic but controlled shadows. Avoid random clutter, too many competing palettes, cheap shine and visual noise without hierarchy.$maximal$, 'Кураторский максимализм: jewel tones, бархат и галерея', false, 160),
  ('mediterranean', 'Средиземноморский модерн', 'terra', $med$Mediterranean Modern / Modern Tuscan interior: warm plaster, terracotta, arches, brass and indoor-outdoor living; a warm alternative to Scandinavian white. Base palette: warm white stucco, sand and terracotta; contrast: olive green and dusty blue; accents: aged brass and burnt sienna. Materials: lime plaster, terracotta tile, rattan, linen and unglazed ceramics. Feature wall: a real or painted arch, a ceramic niche or textured plaster. Lighting: warm daylight around 3000–3500K and a golden evening mood. Avoid Greek-hotel kitsch, blue-and-white clichés, gloss and plastic.$med$, 'Терракота, тёплая штукатурка, арки и средиземноморский свет', false, 170)
